    var container = document.getElementById(containerId);
    if (!container) return;

    if (typeof echarts === 'undefined') {
        container.innerHTML = '<p style="color:#999;text-align:center;padding:30px 0;">ECharts failed to load.</p>';
        return;
    }

    if (!rows || rows.length === 0) {
