    options = options || {};

    var title = options.title || '';
    var orientation = options.orientation || 'gene_x_cluster_y';
    var dotScale = Number(options.dotScale || 2.2);

    if (isNaN(dotScale) || dotScale <= 0) {
        dotScale = 2.2;
    }

